import type { z } from "zod";

/**
 * A type made read-only all the way down.
 *
 * For wire types generated by someone else (Google's, from @googleapis/*),
 * which are declared mutable. The servers here never change a response in
 * place, and this makes the compiler say so rather than a comment.
 */
export type DeepReadonly<T> = T extends (infer U)[]
  ? readonly DeepReadonly<U>[]
  : T extends readonly (infer U)[]
    ? readonly DeepReadonly<U>[]
    : T extends object
      ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
      : T;

/**
 * A generated wire type as it really arrives: read-only all the way down, and
 * every OPTIONAL field may also be `null`, not only absent.
 *
 * OpenAPI generators type an optional field as `T | undefined`, and APIs send
 * `null` for it anyway. Enable Banking's spec types
 * `HalTransactions.continuation_key` as a string while its own prose says
 * "Null if there are no more pages", and production sends the null (echo it
 * back as the string "null" and the next page request fails with 422).
 * Widening every optional field makes the compiler ask what the code does with
 * one. Required fields are taken at the spec's word.
 */
export type Wire<T> = T extends readonly (infer U)[]
  ? readonly Wire<U>[]
  : T extends object
    ? { readonly [K in keyof T]: {} extends Pick<T, K> ? Wire<NonNullable<T[K]>> | null : Wire<T[K]> }
    : T;

/**
 * What a tool with an output schema answers, as its controller declares it:
 * the schema's type, read-only all the way down, so a use case returning its
 * own read-only types is checked against the schema by the compiler and a
 * field it stops filling fails the typecheck, before the guard's runtime check.
 */
export type OutputOf<S extends z.ZodType> = DeepReadonly<z.output<S>>;
